package googleapi

import (
	"context"
	"errors"
	"testing"

	"github.com/openclaw/gogcli/internal/config"
)

func TestStoredAuthRequiresDependencies(t *testing.T) {
	t.Parallel()

	_, err := optionsForAccountScopes(context.Background(), "drive", "a@b.com", []string{"scope"})
	if !errors.Is(err, errAuthDependenciesRequired) {
		t.Fatalf("error = %v, want %v", err, errAuthDependenciesRequired)
	}
}

func TestADCRequiresTokenSourceFactory(t *testing.T) {
	t.Parallel()

	ctx := WithAuthDependencies(context.Background(), AuthDependencies{Mode: AuthModeADC})

	_, err := optionsForAccountScopes(ctx, "drive", "adc", []string{"scope"})
	if !errors.Is(err, errADCTokenSourceRequired) {
		t.Fatalf("error = %v, want %v", err, errADCTokenSourceRequired)
	}
}

func TestClientCredentialsRequireExplicitDependencies(t *testing.T) {
	t.Parallel()

	_, _, err := clientCredentialsForAccount(context.Background(), AuthDependencies{}, "a@b.com")
	if !errors.Is(err, errAuthClientResolverRequired) {
		t.Fatalf("resolver error = %v, want %v", err, errAuthClientResolverRequired)
	}

	dependencies := AuthDependencies{
		ResolveClient: func(string, string) (string, error) {
			return config.DefaultClientName, nil
		},
	}

	_, _, err = clientCredentialsForAccount(context.Background(), dependencies, "a@b.com")
	if !errors.Is(err, errAuthCredentialsReaderRequired) {
		t.Fatalf("credentials error = %v, want %v", err, errAuthCredentialsReaderRequired)
	}
}

func TestTokenSourceRequiresExplicitTokenStore(t *testing.T) {
	t.Parallel()

	_, err := tokenSourceForAccountScopesWithStoredScopeCheck(
		context.Background(),
		AuthDependencies{},
		"drive",
		"a@b.com",
		config.DefaultClientName,
		"id",
		"secret",
		[]string{"scope"},
		false,
	)
	if !errors.Is(err, errAuthTokenStoreOpenerRequired) {
		t.Fatalf("error = %v, want %v", err, errAuthTokenStoreOpenerRequired)
	}
}

func TestEmailReferenceUpdateRequiresDependency(t *testing.T) {
	t.Parallel()

	err := (AuthDependencies{}).updateEmailReferences("old@example.com", "new@example.com")
	if !errors.Is(err, errEmailReferenceUpdaterRequired) {
		t.Fatalf("error = %v, want %v", err, errEmailReferenceUpdaterRequired)
	}
}

package googleapi

import (
	"context"
	"errors"
	"fmt"
	"sync"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"

	"github.com/openclaw/gogcli/internal/authclient"
	"github.com/openclaw/gogcli/internal/config"
	"github.com/openclaw/gogcli/internal/googleauth"
	"github.com/openclaw/gogcli/internal/secrets"
)

type AuthMode string

const (
	AuthModeStored AuthMode = ""
	AuthModeADC    AuthMode = "adc"
)

type (
	ServiceAccountStoreResolver   func() (*config.ServiceAccountStore, error)
	ADCTokenSourceFunc            func(context.Context, ...string) (oauth2.TokenSource, error)
	ServiceAccountTokenSourceFunc func(context.Context, []byte, string, []string) (oauth2.TokenSource, error)
)

// ReauthCoordinator serializes interactive recovery across every Google
// service client created for one command invocation.
type ReauthCoordinator struct {
	mu sync.Mutex
}

func NewReauthCoordinator() *ReauthCoordinator {
	return &ReauthCoordinator{}
}

func (c *ReauthCoordinator) run(fn func() error) error {
	if c == nil {
		return fn()
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	return fn()
}

// ReauthFunc attempts to re-authorize the given account by launching a
// browser-based OAuth flow and persisting the new refresh token. It is
// called automatically when the stored refresh token is expired or revoked
// (invalid_grant) and the session is interactive.
//
// storedToken, if non-nil, carries the full scope/service set from the
// original authorization so the reauth can preserve the grant width.
// Returns the replacement token metadata. The token-source owner persists it
// and swaps the in-memory refresh token as one serialized operation.
type ReauthFunc func(ctx context.Context, email string, client string, services []string, scopes []string, storedToken *secrets.Token) (secrets.Token, error)

type AuthDependencies struct {
	ResolveClient             authclient.ClientResolver
	ReadCredentials           authclient.CredentialsReader
	OpenTokens                authclient.SecretsStoreOpener
	ServiceAccounts           ServiceAccountStoreResolver
	UpdateEmailReferences     googleauth.EmailReferenceUpdater
	Mode                      AuthMode
	ADCTokenSource            ADCTokenSourceFunc
	ServiceAccountTokenSource ServiceAccountTokenSourceFunc
	Reauth                    ReauthFunc
	ReauthCoordinator         *ReauthCoordinator
}

var (
	errAuthDependenciesRequired          = errors.New("google API auth dependencies are required")
	errAuthClientResolverRequired        = errors.New("google API auth client resolver is required")
	errAuthCredentialsReaderRequired     = errors.New("google API auth credentials reader is required")
	errAuthTokenStoreOpenerRequired      = errors.New("google API auth token store opener is required")
	errServiceAccountStoreRequired       = errors.New("service account store resolver is required")
	errEmailReferenceUpdaterRequired     = errors.New("google API auth email reference updater is required")
	errADCTokenSourceRequired            = errors.New("ADC token source factory is required")
	errServiceAccountTokenSourceRequired = errors.New("service account token source factory is required")
)

type authDependenciesContextKey struct{}

func ParseAuthMode(value string) AuthMode {
	if value == string(AuthModeADC) {
		return AuthModeADC
	}

	return AuthModeStored
}

func WithAuthDependencies(ctx context.Context, dependencies AuthDependencies) context.Context {
	return context.WithValue(ctx, authDependenciesContextKey{}, dependencies)
}

func authDependenciesFromContext(ctx context.Context) (AuthDependencies, bool) {
	if ctx == nil {
		return AuthDependencies{}, false
	}

	dependencies, ok := ctx.Value(authDependenciesContextKey{}).(AuthDependencies)

	return dependencies, ok
}

func requireAuthDependencies(ctx context.Context) (AuthDependencies, error) {
	dependencies, ok := authDependenciesFromContext(ctx)
	if !ok {
		return AuthDependencies{}, errAuthDependenciesRequired
	}

	return dependencies, nil
}

func (d AuthDependencies) resolveClient(email, override string) (string, error) {
	if d.ResolveClient == nil {
		return "", errAuthClientResolverRequired
	}

	client, err := d.ResolveClient(email, override)
	if err != nil {
		return "", fmt.Errorf("resolve client: %w", err)
	}

	return client, nil
}

func (d AuthDependencies) readCredentials(client string) (config.ClientCredentials, error) {
	if d.ReadCredentials == nil {
		return config.ClientCredentials{}, errAuthCredentialsReaderRequired
	}

	credentials, err := d.ReadCredentials(client)
	if err != nil {
		return config.ClientCredentials{}, fmt.Errorf("read credentials: %w", err)
	}

	return credentials, nil
}

func (d AuthDependencies) openTokens() (secrets.Store, error) {
	if d.OpenTokens == nil {
		return nil, errAuthTokenStoreOpenerRequired
	}

	store, err := d.OpenTokens()
	if err != nil {
		return nil, fmt.Errorf("open token store: %w", err)
	}

	if store == nil {
		return nil, errAuthTokenStoreOpenerRequired
	}

	return store, nil
}

func (d AuthDependencies) serviceAccountStore() (*config.ServiceAccountStore, error) {
	if d.ServiceAccounts == nil {
		return nil, errServiceAccountStoreRequired
	}

	store, err := d.ServiceAccounts()
	if err != nil {
		return nil, fmt.Errorf("resolve service account store: %w", err)
	}

	if store == nil {
		return nil, errServiceAccountStoreRequired
	}

	return store, nil
}

func (d AuthDependencies) updateEmailReferences(oldEmail, newEmail string) error {
	if d.UpdateEmailReferences == nil {
		return errEmailReferenceUpdaterRequired
	}

	if err := d.UpdateEmailReferences(oldEmail, newEmail); err != nil {
		return fmt.Errorf("update email references: %w", err)
	}

	return nil
}

func (d AuthDependencies) adcTokenSource(ctx context.Context, scopes []string) (oauth2.TokenSource, error) {
	if d.ADCTokenSource == nil {
		return nil, errADCTokenSourceRequired
	}

	tokenSource, err := d.ADCTokenSource(ctx, scopes...)
	if err != nil {
		return nil, fmt.Errorf("ADC token source: %w", err)
	}

	return tokenSource, nil
}

func (d AuthDependencies) serviceAccountTokenSource(ctx context.Context, keyJSON []byte, subject string, scopes []string) (oauth2.TokenSource, error) {
	if d.ServiceAccountTokenSource == nil {
		return nil, errServiceAccountTokenSourceRequired
	}

	return d.ServiceAccountTokenSource(ctx, keyJSON, subject, scopes)
}

func DefaultADCTokenSource(ctx context.Context, scopes ...string) (oauth2.TokenSource, error) {
	tokenSource, err := google.DefaultTokenSource(ctx, scopes...)
	if err != nil {
		return nil, fmt.Errorf("default token source: %w", err)
	}

	return tokenSource, nil
}

// noInputContextKey controls whether auto-reauth is suppressed. When
// --no-input is set (or stdin is not a terminal), the auto-reauth fallback
// must not launch a browser.
type noInputContextKey struct{}

// WithNoInput marks the context as non-interactive. Auto-reauth will be
// suppressed and a clear error message with manual instructions is returned
// instead.
func WithNoInput(ctx context.Context) context.Context {
	return context.WithValue(ctx, noInputContextKey{}, true)
}

// NoInputFromContext reports whether the context was marked non-interactive.
func NoInputFromContext(ctx context.Context) bool {
	if ctx == nil {
		return false
	}

	enabled, _ := ctx.Value(noInputContextKey{}).(bool)

	return enabled
}

package cmd

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"strings"
	"testing"

	"github.com/openclaw/gogcli/internal/authclient"
	"github.com/openclaw/gogcli/internal/googleapi"
	"github.com/openclaw/gogcli/internal/googleauth"
)

func TestAuthSetupDryRun(t *testing.T) {
	var stdout bytes.Buffer
	ctx := newCmdRuntimeJSONOutputContext(t, &stdout, &bytes.Buffer{})
	err := (&AuthSetupCmd{
		Email:         "user@example.com",
		Project:       "gog-test-project",
		ServicesCSV:   "gmail,docs",
		CreateProject: true,
		EnableAPIs:    true,
		Credentials:   "/tmp/client.json",
		Login:         true,
	}).Run(ctx, &RootFlags{DryRun: true, NoInput: true, ReadOnly: true})
	if ExitCode(err) != 0 {
		t.Fatalf("exit code = %d, want 0: %v", ExitCode(err), err)
	}

	var got struct {
		DryRun  bool   `json:"dry_run"`
		Op      string `json:"op"`
		Request struct {
			Project  string   `json:"project"`
			APIs     []string `json:"apis"`
			Readonly bool     `json:"readonly"`
		} `json:"request"`
	}
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("decode: %v\n%s", err, stdout.String())
	}
	if !got.DryRun || got.Op != "auth.setup" || got.Request.Project != "gog-test-project" || !got.Request.Readonly {
		t.Fatalf("unexpected dry-run: %#v", got)
	}
	wantAPIs := []string{"docs.googleapis.com", "drive.googleapis.com", "gmail.googleapis.com"}
	if strings.Join(got.Request.APIs, ",") != strings.Join(wantAPIs, ",") {
		t.Fatalf("apis = %#v, want %#v", got.Request.APIs, wantAPIs)
	}
}

func TestAuthSetupGuidance(t *testing.T) {
	result := authSetupResult{
		Project:  "gog-test-project",
		Services: []string{"gmail", "drive"},
	}
	steps := authSetupNextSteps(&AuthSetupCmd{Email: "user@example.com"}, result, true, "work", true)
	joined := strings.Join(steps, "\n")
	for _, want := range []string{"auth/branding?project=gog-test-project", "auth/clients?project=gog-test-project", "gog --client work auth credentials", "gog --client work --readonly auth add user@example.com --services gmail,drive", "gog auth doctor --check"} {
		if !strings.Contains(joined, want) {
			t.Fatalf("guidance missing %q:\n%s", want, joined)
		}
	}
}

func TestAuthSetupClientMatchesLoginResolution(t *testing.T) {
	ctx := authclient.WithClientResolver(context.Background(), func(email string, override string) (string, error) {
		if email != "user@example.com" || override != "" {
			t.Fatalf("resolver args = %q, %q", email, override)
		}

		return "mapped-client", nil
	})

	client, err := authSetupClient(ctx, "user@example.com")
	if err != nil {
		t.Fatal(err)
	}
	if client != "mapped-client" {
		t.Fatalf("client = %q, want mapped-client", client)
	}
}

func TestAuthSetupValidation(t *testing.T) {
	tests := []struct {
		name string
		cmd  AuthSetupCmd
		want string
	}{
		{name: "invalid project", cmd: AuthSetupCmd{Project: "BAD"}, want: "invalid --gcloud-project"},
		{name: "login email", cmd: AuthSetupCmd{Project: "valid-project", Login: true}, want: "--login requires an email"},
		{name: "create project", cmd: AuthSetupCmd{CreateProject: true}, want: "--create-project requires --gcloud-project"},
		{name: "open console", cmd: AuthSetupCmd{OpenConsole: true, Credentials: "/not/read.json"}, want: "--open-console requires --gcloud-project"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Setenv("PATH", t.TempDir())
			err := tt.cmd.Run(context.Background(), &RootFlags{})
			if err == nil || !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("error = %v, want %q", err, tt.want)
			}
		})
	}
}

func TestAuthSetupReadOnlyBlocksGcloudMutations(t *testing.T) {
	t.Setenv("PATH", t.TempDir())
	err := (&AuthSetupCmd{Project: "valid-project", CreateProject: true}).Run(context.Background(), &RootFlags{ReadOnly: true})
	if !errors.Is(err, googleapi.ErrReadOnly) {
		t.Fatalf("error = %v, want ErrReadOnly", err)
	}
}

func TestAPIServiceIDsForServices(t *testing.T) {
	got, err := googleauth.APIServiceIDsForServices([]googleauth.Service{
		googleauth.ServiceSheets,
		googleauth.ServiceDocs,
		googleauth.ServiceDrive,
	})
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"docs.googleapis.com", "drive.googleapis.com", "sheets.googleapis.com"}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

package googleauth

import "testing"

func TestOpenBrowserCommand(t *testing.T) {
	name, args := openBrowserCommand("https://example.com", "darwin")
	if name != "open" || len(args) != 1 || args[0] != "https://example.com" {
		t.Fatalf("darwin: %q %#v", name, args)
	}

	name, args = openBrowserCommand("https://example.com", "windows")
	if name != "rundll32" || len(args) != 2 || args[1] != "https://example.com" {
		t.Fatalf("windows: %q %#v", name, args)
	}

	name, args = openBrowserCommand("https://example.com", "linux")
	if name != "xdg-open" || len(args) != 1 || args[0] != "https://example.com" {
		t.Fatalf("linux: %q %#v", name, args)
	}
}

func TestOpenBrowser_UsesStartCommand(t *testing.T) {
	orig := startCommand

	t.Cleanup(func() { startCommand = orig })

	var gotName string
	var gotArgs []string
	startCommand = func(name string, args ...string) error {
		gotName = name

		gotArgs = append([]string(nil), args...)

		return nil
	}

	if err := openBrowser("https://example.com"); err != nil {
		t.Fatalf("openBrowser: %v", err)
	}

	if gotName == "" || len(gotArgs) == 0 {
		t.Fatalf("expected startCommand to be called")
	}

	if gotArgs[len(gotArgs)-1] != "https://example.com" {
		t.Fatalf("unexpected args: %q %#v", gotName, gotArgs)
	}
}

package googleapi

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"testing"

	"golang.org/x/oauth2"
)

var (
	errAutoReauthNetworkTimeout      = errors.New("network timeout")
	errAutoReauthUntypedInvalidGrant = errors.New(`oauth2: "invalid_grant" "Bad Request"`)
	errAutoReauthBrowserNotOpen      = errors.New("browser did not open")
)

func TestIsInvalidGrantError(t *testing.T) {
	tests := []struct {
		name string
		err  error
		want bool
	}{
		{
			name: "nil error",
			err:  nil,
			want: false,
		},
		{
			name: "unrelated error",
			err:  errAutoReauthNetworkTimeout,
			want: false,
		},
		{
			name: `invalid_grant with "Token has been expired or revoked"`,
			err:  invalidGrantError(),
			want: true,
		},
		{
			name: "untyped invalid_grant text",
			err:  errAutoReauthUntypedInvalidGrant,
			want: false,
		},
		{
			name: "wrapped invalid_grant",
			err:  fmt.Errorf("refresh access token: %w", invalidGrantError()),
			want: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := isInvalidGrantError(tt.err); got != tt.want {
				t.Errorf("isInvalidGrantError() = %v, want %v", got, tt.want)
			}
		})
	}
}

func invalidGrantError() error {
	return &oauth2.RetrieveError{
		ErrorCode:        "invalid_grant",
		ErrorDescription: "Token has been expired or revoked.",
	}
}

func TestRetryTransportAutoReauthOnInvalidGrant(t *testing.T) {
	tokenSource := &refreshableTestTokenSource{token: "stale-token"}
	reauthCalls := 0
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++

		body, err := io.ReadAll(req.Body)
		if err != nil {
			return nil, fmt.Errorf("read body: %w", err)
		}
		_ = body

		switch calls {
		case 1:
			// First call: the oauth2 transport will fail with invalid_grant
			// because the refresh token is stale. We simulate this by
			// returning an error from the base transport.
			return nil, invalidGrantError()
		case 2:
			// After reauth, the token should be fresh.
			if got := req.Header.Get("Authorization"); got != "Bearer fresh-token" {
				t.Fatalf("second authorization = %q, want %q", got, "Bearer fresh-token")
			}

			return newTestResponse(http.StatusOK, "ok"), nil
		default:
			t.Fatalf("unexpected call %d", calls)
			return nil, errUnexpectedRequestBody
		}
	})

	rt := &RetryTransport{
		Base: &oauth2TransportWrapper{
			source: tokenSource,
			base:   base,
		},
		MaxRetries429: 0,
		MaxRetries5xx: 0,
		BaseDelay:     0,
		Reauth: func(ctx context.Context) error {
			reauthCalls++
			tokenSource.token = "fresh-token"

			return nil
		},
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodPost, "http://example.com", io.NopCloser(strings.NewReader("payload")))
	if err != nil {
		t.Fatalf("new request: %v", err)
	}
	req.ContentLength = int64(len("payload"))

	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("round trip: %v", err)
	}
	_ = resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		t.Fatalf("unexpected status: %d", resp.StatusCode)
	}

	if calls != 2 {
		t.Fatalf("calls = %d, want 2", calls)
	}

	if reauthCalls != 1 {
		t.Fatalf("reauth calls = %d, want 1", reauthCalls)
	}
}

func TestRetryTransportAutoReauthFailureSurfacesError(t *testing.T) {
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		_ = req.Body

		return nil, invalidGrantError()
	})

	rt := &RetryTransport{
		Base: base,
		Reauth: func(context.Context) error {
			return errAutoReauthBrowserNotOpen
		},
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, "http://example.com", nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}

	resp, err := rt.RoundTrip(req)
	if resp != nil {
		_ = resp.Body.Close()
	}

	if err == nil {
		t.Fatalf("expected error")
	}

	if !strings.Contains(err.Error(), "invalid_grant") {
		t.Fatalf("error should mention invalid_grant: %v", err)
	}

	if !strings.Contains(err.Error(), "re-authentication failed") {
		t.Fatalf("error should mention re-authentication failed: %v", err)
	}

	if calls != 1 {
		t.Fatalf("calls = %d, want 1", calls)
	}
}

func TestRetryTransportNoReauthWhenNil(t *testing.T) {
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		return nil, invalidGrantError()
	})

	rt := &RetryTransport{
		Base:   base,
		Reauth: nil, // No reauth function
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, "http://example.com", nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}

	resp, err := rt.RoundTrip(req)
	if resp != nil {
		_ = resp.Body.Close()
	}

	if err == nil {
		t.Fatalf("expected error")
	}

	if !strings.Contains(err.Error(), "invalid_grant") {
		t.Fatalf("error should contain invalid_grant: %v", err)
	}

	if !strings.Contains(err.Error(), "gog auth add") {
		t.Fatalf("error should contain 'gog auth add' hint: %v", err)
	}

	if calls != 1 {
		t.Fatalf("calls = %d, want 1", calls)
	}
}

func TestRetryTransportNoReauthWhenRetriesDisabled(t *testing.T) {
	reauthCalls := 0
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		return nil, invalidGrantError()
	})

	rt := &RetryTransport{
		Base: base,
		Reauth: func(context.Context) error {
			reauthCalls++
			return nil
		},
	}

	ctx := WithoutRetries(context.Background())

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://example.com", nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}

	resp, err := rt.RoundTrip(req)
	if resp != nil {
		_ = resp.Body.Close()
	}

	if err == nil {
		t.Fatalf("expected error")
	}

	if !strings.Contains(err.Error(), "invalid_grant") {
		t.Fatalf("error should contain invalid_grant: %v", err)
	}

	if !strings.Contains(err.Error(), "gog auth add") {
		t.Fatalf("error should contain 'gog auth add' hint: %v", err)
	}

	if reauthCalls != 0 {
		t.Fatalf("reauth should not be called when retries are disabled, got %d calls", reauthCalls)
	}

	if calls != 1 {
		t.Fatalf("calls = %d, want 1", calls)
	}
}

func TestRetryTransportNoReauthForNonReplayableBody(t *testing.T) {
	reauthCalls := 0
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		body, _ := io.ReadAll(req.Body)
		_ = body

		return nil, invalidGrantError()
	})

	rt := &RetryTransport{
		Base: base,
		Reauth: func(context.Context) error {
			reauthCalls++
			return nil
		},
	}

	// Non-replayable: large body with unknown content length
	req, err := http.NewRequestWithContext(context.Background(), http.MethodPost, "http://example.com", io.NopCloser(strings.NewReader("payload")))
	if err != nil {
		t.Fatalf("new request: %v", err)
	}
	req.ContentLength = maxBufferedReplayBodyBytes + 1

	resp, err := rt.RoundTrip(req)
	if resp != nil {
		_ = resp.Body.Close()
	}

	if err == nil {
		t.Fatalf("expected error")
	}

	if !strings.Contains(err.Error(), "invalid_grant") {
		t.Fatalf("error should contain invalid_grant: %v", err)
	}

	if !strings.Contains(err.Error(), "gog auth add") {
		t.Fatalf("error should contain 'gog auth add' hint: %v", err)
	}

	if reauthCalls != 0 {
		t.Fatalf("reauth should not be called for non-replayable body, got %d calls", reauthCalls)
	}
}

func TestRetryTransportReauthOnlyOnce(t *testing.T) {
	reauthCalls := 0
	calls := 0

	base := roundTripFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		// Always return invalid_grant, even after reauth
		return nil, invalidGrantError()
	})

	rt := &RetryTransport{
		Base: base,
		Reauth: func(context.Context) error {
			reauthCalls++
			return nil
		},
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, "http://example.com", nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}

	resp, err := rt.RoundTrip(req)
	if resp != nil {
		_ = resp.Body.Close()
	}

	if err == nil {
		t.Fatalf("expected error")
	}

	if !strings.Contains(err.Error(), "invalid_grant") {
		t.Fatalf("error should contain invalid_grant: %v", err)
	}

	if !strings.Contains(err.Error(), "gog auth add") {
		t.Fatalf("error should contain 'gog auth add' hint: %v", err)
	}

	// Should only reauth once, not loop
	if reauthCalls != 1 {
		t.Fatalf("reauth calls = %d, want 1", reauthCalls)
	}

	if calls != 2 {
		t.Fatalf("calls = %d, want 2", calls)
	}
}

