package googleapi

import (
	"testing"
	"time"
)

func TestCircuitBreakerRecordFailureAndReset(t *testing.T) {
	cb := NewCircuitBreaker()

	for i := 0; i < CircuitBreakerThreshold-1; i++ {
		if opened := cb.RecordFailure(); opened {
			t.Fatalf("unexpected open at %d", i)
		}
	}

	if cb.IsOpen() {
		t.Fatalf("expected closed before threshold")
	}

	if opened := cb.RecordFailure(); !opened {
		t.Fatalf("expected circuit to open")
	}

	if !cb.IsOpen() {
		t.Fatalf("expected open")
	}

	cb.lastFailure = time.Now().Add(-CircuitBreakerResetTime - time.Second)
	if cb.IsOpen() {
		t.Fatalf("expected reset after timeout")
	}

	if cb.State() != circuitStateClosed {
		t.Fatalf("expected closed state")
	}

	if cb.failures != 0 {
		t.Fatalf("expected failures reset")
	}
}

func TestCircuitBreakerRecordSuccessResets(t *testing.T) {
	cb := NewCircuitBreaker()
	cb.open = true
	cb.failures = CircuitBreakerThreshold

	cb.RecordSuccess()

	if cb.State() != circuitStateClosed {
		t.Fatalf("expected closed after success")
	}

	if cb.failures != 0 {
		t.Fatalf("expected failures reset")
	}
}

package googleapi

import (
	"testing"
	"time"
)

func TestCircuitBreaker_OpenAndReset(t *testing.T) {
	cb := NewCircuitBreaker()
	if cb.State() != "closed" {
		t.Fatalf("expected closed, got %q", cb.State())
	}

	for i := 0; i < CircuitBreakerThreshold; i++ {
		opened := cb.RecordFailure()
		if i == CircuitBreakerThreshold-1 && !opened {
			t.Fatalf("expected circuit to open on threshold")
		}
	}

	if !cb.IsOpen() {
		t.Fatalf("expected open")
	}

	if cb.State() != "open" {
		t.Fatalf("expected open state")
	}

	// Force timeout-based reset path.
	cb.lastFailure = time.Now().Add(-(CircuitBreakerResetTime + time.Second))
	if cb.IsOpen() {
		t.Fatalf("expected closed after timeout")
	}

	if cb.State() != "closed" {
		t.Fatalf("expected closed after timeout")
	}

	// Explicit success reset path.
	cb.RecordFailure()
	cb.RecordSuccess()

	if cb.State() != "closed" {
		t.Fatalf("expected closed after success")
	}
}

package cmd

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"sync"
	"testing"

	"github.com/mark3labs/mcp-go/mcp"
