		t.Fatalf("recipients = to:%q cc:%q bcc:%q", msg["to"], msg["cc"], msg["bcc"])
	}
	if strings.Contains(stdout, `"body"`) {
		t.Fatalf("unexpected body: %s", stdout)
	}
