	}
	if got := ctx.Command(); got != "auth add <email>" {
		t.Fatalf("command = %q, want auth add <email>", got)
	}
	if got := cli.Auth.Add.Email; got != "you@example.com" {
		t.Fatalf("email = %q, want you@example.com", got)
	}
}

