func TestCacheMessageRoundTripUsesHashedInjectedPath(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	cache, cacheErr := NewCache(root)
	if cacheErr != nil {
		t.Fatalf("NewCache: %v", cacheErr)
	}
	message := Message{ID: "msg-one", ThreadID: "thread-one", Raw: "raw"}
	if writeErr := cache.WriteMessage("accthash", message); writeErr != nil {
		t.Fatalf("WriteMessage: %v", writeErr)
	}
	got, ok, readErr := cache.ReadMessage("accthash", message.ID)
	if readErr != nil {
		t.Fatalf("ReadMessage: %v", readErr)
	}

	if !ok || got.ID != message.ID || got.ThreadID != message.ThreadID || got.Raw != message.Raw {
		t.Fatalf("message = %#v ok=%t", got, ok)
	}

	path, ok := cache.MessagePath("accthash", message.ID)
	if !ok {
		t.Fatal("MessagePath unavailable")
	}

	if !strings.HasPrefix(path, root+string(filepath.Separator)) {
		t.Fatalf("path %q is outside root %q", path, root)
	}
	if strings.Contains(path, message.ID) {
		t.Fatalf("path exposes message ID: %q", path)
	}
}

func TestCacheMessageRejectsWrongID(t *testing.T) {
	t.Parallel()
	cache, cacheErr := NewCache(t.TempDir())
	if cacheErr != nil {
		t.Fatalf("NewCache: %v", cacheErr)
	}
	path, ok := cache.MessagePath("accthash", "msg-one")
	if !ok {
		t.Fatal("MessagePath unavailable")
	}
	if mkdirErr := os.MkdirAll(filepath.Dir(path), 0o700); mkdirErr != nil {
		t.Fatalf("MkdirAll: %v", mkdirErr)
	}
	data, err := json.Marshal(Message{ID: "other", Raw: "raw"})
	if err != nil {
		t.Fatalf("Marshal: %v", err)
	}

	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	if _, _, err := cache.ReadMessage("accthash", "msg-one"); err == nil {
		t.Fatal("expected wrong cache ID to fail")
	}
}

func TestCacheListStateRoundTripAndSelectionIsolation(t *testing.T) {
	t.Parallel()

	cache, cacheErr := NewCache(t.TempDir())
	if cacheErr != nil {
		t.Fatalf("NewCache: %v", cacheErr)
	}
	selection := Selection{
		AccountHash:      "accthash",
		Query:            "in:inbox",
		Max:              10,
		IncludeSpamTrash: true,
	}
	if writeErr := cache.WriteListState(selection, []string{"m1"}, "next", false); writeErr != nil {
		t.Fatalf("WriteListState: %v", writeErr)
	}

	state, ok, err := cache.ReadListState(selection)
	if err != nil {
		t.Fatalf("ReadListState: %v", err)
	}

	if !ok || state.PageToken != "next" || len(state.IDs) != 1 || state.IDs[0] != "m1" {
		t.Fatalf("state = %#v ok=%t", state, ok)
	}
	other := selection
	other.Query = "in:sent"
	if _, ok, err := cache.ReadListState(other); err != nil || ok {
		t.Fatalf("other selection ok=%t err=%v", ok, err)
	}
}

func TestCacheShardDirsStayUnderInjectedRoot(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	cache, err := NewCache(root)
	if err != nil {
		t.Fatalf("NewCache: %v", err)
	}
	messageDir, ok := cache.MessageShardDir("accthash")
	if !ok || !strings.HasPrefix(messageDir, root+string(filepath.Separator)) {
		t.Fatalf("message dir = %q ok=%t", messageDir, ok)
	}
	checkpointDir, ok := cache.CheckpointShardDir("accthash", "run-test")
	if !ok || !strings.HasPrefix(checkpointDir, root+string(filepath.Separator)) {
		t.Fatalf("checkpoint dir = %q ok=%t", checkpointDir, ok)
	}

	for _, invalid := range []string{"../escape", "nested/path", `nested\path`} {
		if _, ok := cache.MessageShardDir(invalid); ok {
			t.Fatalf("MessageShardDir(%q) succeeded", invalid)
		}

		if _, ok := cache.CheckpointShardDir("accthash", invalid); ok {
			t.Fatalf("CheckpointShardDir(%q) succeeded", invalid)
		}
	}
}

package cmd

import (
	"context"
	"fmt"
	"net/url"
	"os"
	"os/exec"
	"runtime"
	"strings"

	"github.com/openclaw/gogcli/internal/authclient"
	"github.com/openclaw/gogcli/internal/config"
	"github.com/openclaw/gogcli/internal/googleapi"
	"github.com/openclaw/gogcli/internal/googleauth"
	"github.com/openclaw/gogcli/internal/outfmt"
	"github.com/openclaw/gogcli/internal/ui"
)

type AuthSetupCmd struct {
	Email         string `arg:"" optional:"" name:"email" help:"Google account to authorize after setup"`
	Project       string `name:"gcloud-project" aliases:"project-id" help:"Google Cloud project ID (default: active gcloud project)"`
	ProjectName   string `name:"project-name" help:"Display name when creating a project" default:"gog CLI"`
	ServicesCSV   string `name:"services" help:"Services to configure: comma-separated ${auth_services}" default:"gmail,calendar,drive,docs,sheets,contacts"`
	Credentials   string `name:"credentials" type:"path" help:"Downloaded Desktop OAuth client JSON to store"`
	CreateProject bool   `name:"create-project" help:"Create --gcloud-project with gcloud (requires confirmation)"`
	EnableAPIs    bool   `name:"enable-apis" help:"Enable selected Google APIs with gcloud"`
	Login         bool   `name:"login" help:"Run browser OAuth after project/client setup"`
	ForceConsent  bool   `name:"force-consent" help:"Force OAuth consent when --login runs"`
	OpenConsole   bool   `name:"open-console" help:"Open the OAuth client page for the selected project"`
}

type authSetupResult struct {
	Status           string   `json:"status"`
	Project          string   `json:"project,omitempty"`
	GcloudAccount    string   `json:"gcloud_account,omitempty"`
	Services         []string `json:"services"`
	APIs             []string `json:"apis"`
	ProjectCreated   bool     `json:"project_created"`
	APIsEnabled      bool     `json:"apis_enabled"`
	CredentialsSaved bool     `json:"credentials_saved"`
	NextSteps        []string `json:"next_steps"`
}

func (c *AuthSetupCmd) Run(ctx context.Context, flags *RootFlags) error {
	readonly := readOnlyEnabled(flags)
	services, err := parseAuthServices(c.ServicesCSV)
	if err != nil {
		return err
	}
	serviceNames := make([]string, 0, len(services))
	for _, service := range services {
		serviceNames = append(serviceNames, string(service))
	}
	apiIDs, err := googleauth.APIServiceIDsForServices(services)
	if err != nil {
		return usage(err.Error())
	}

	project := strings.TrimSpace(c.Project)
	account := ""
	gcloudAvailable := authSetupGcloudAvailable()
	if gcloudAvailable {
		account, _ = authSetupGcloudValue(ctx, "account")
		if project == "" {
			project, _ = authSetupGcloudValue(ctx, "project")
		}
	}
	if project != "" && !validGoogleCloudProjectID(project) {
		return usagef("invalid --gcloud-project %q (use 6-30 lowercase letters, digits, or hyphens; start with a letter)", project)
	}
	if c.CreateProject && project == "" {
		return usage("--create-project requires --gcloud-project")
	}
	if c.EnableAPIs && project == "" {
		return usage("--enable-apis requires --gcloud-project or an active gcloud project")
	}
	if c.OpenConsole && project == "" {
		return usage("--open-console requires --gcloud-project or an active gcloud project")
	}
	if readonly && (c.CreateProject || c.EnableAPIs) && (flags == nil || !flags.DryRun) {
		return fmt.Errorf("%w: auth setup project/API mutations are disabled", googleapi.ErrReadOnly)
	}
	if (c.CreateProject || c.EnableAPIs) && !gcloudAvailable && (flags == nil || !flags.DryRun) {
		return usage("gcloud is required for --create-project or --enable-apis; install it or omit those flags for manual guidance")
	}
	if c.Login && strings.TrimSpace(c.Email) == "" {
		return usage("--login requires an email argument")
	}
	if c.Login && flags != nil && flags.NoInput && !flags.DryRun {
		return usage("--login requires interactive browser input; omit --no-input or run `gog auth import`")
	}
	if c.OpenConsole && flags != nil && flags.NoInput && !flags.DryRun {
		return usage("--open-console is not available with --no-input")
	}

	plan := map[string]any{
		"project":          project,
		"project_name":     strings.TrimSpace(c.ProjectName),
		"services":         serviceNames,
		"apis":             apiIDs,
		"create_project":   c.CreateProject,
		"enable_apis":      c.EnableAPIs,
		"credentials_file": strings.TrimSpace(c.Credentials),
		"login_email":      strings.TrimSpace(c.Email),
		"readonly":         readonly,
		"force_consent":    c.ForceConsent,
		"open_console":     c.OpenConsole,
	}
	if dryRunErr := dryRunExit(ctx, flags, "auth.setup", plan); dryRunErr != nil {
		return dryRunErr
	}

	result := authSetupResult{
		Status:        "guided",
		Project:       project,
		GcloudAccount: account,
		Services:      serviceNames,
		APIs:          apiIDs,
		NextSteps:     []string{},
	}

	if c.CreateProject {
		if err := confirmDestructiveChecked(ctx, flags, "create Google Cloud project "+project); err != nil {
			return err
		}
		args := []string{"projects", "create", project}
		if name := strings.TrimSpace(c.ProjectName); name != "" {
			args = append(args, "--name", name)
		}
		if _, err := authSetupRunGcloud(ctx, args...); err != nil {
			return fmt.Errorf("create Google Cloud project: %w", err)
		}
		result.ProjectCreated = true
	}

	if c.EnableAPIs {
		args := append([]string{"services", "enable"}, apiIDs...)
		args = append(args, "--project", project)
		if _, err := authSetupRunGcloud(ctx, args...); err != nil {
			return fmt.Errorf("enable Google APIs: %w", err)
		}
		result.APIsEnabled = true
	}

	if credentials := strings.TrimSpace(c.Credentials); credentials != "" {
		if err := runAuthSetupCredentials(ctx, flags, credentials, strings.TrimSpace(c.Email)); err != nil {
			return err
		}
		result.CredentialsSaved = true
	}

	if c.OpenConsole {
		if err := openURL(ctx, googleCloudOAuthClientsURL(project)); err != nil {
			return fmt.Errorf("open OAuth client page: %w", err)
		}
	}

	result.NextSteps = authSetupNextSteps(c, result, gcloudAvailable, authclient.ClientOverrideFromContext(ctx), readonly)
	if c.Login {
		return (&AuthAddCmd{
			Email:        strings.TrimSpace(c.Email),
			ServicesCSV:  c.ServicesCSV,
			ForceConsent: c.ForceConsent,
		}).Run(ctx, flags)
	}

	return writeAuthSetupResult(ctx, result)
}

func runAuthSetupCredentials(ctx context.Context, flags *RootFlags, path string, email string) error {
	client, err := authSetupClient(ctx, email)
	if err != nil {
		return err
	}
	expanded, err := config.ExpandPath(path)
	if err != nil {
		return err
	}
	raw, err := os.ReadFile(expanded) //nolint:gosec // explicit user-provided credentials path
	if err != nil {
		return err
	}
	credentials, err := config.ParseGoogleOAuthClientJSON(raw)
	if err != nil {
		return err
	}
	if flags != nil && flags.DryRun {
		return nil
	}
	store, err := commandOAuthCredentialsStore(ctx)
	if err != nil {
		return err
	}
	if err := store.Write(client, credentials, false); err != nil {
		return fmt.Errorf("store OAuth client credentials: %w", err)
	}
	return nil
}

func authSetupClient(ctx context.Context, email string) (string, error) {
	override := authclient.ClientOverrideFromContext(ctx)
	if email != "" {
		return authclient.ResolveClientWithOverride(ctx, email, override)
	}

	return normalizeClientForFlag(override)
}

func authSetupNextSteps(c *AuthSetupCmd, result authSetupResult, gcloudAvailable bool, clientOverride string, readonly bool) []string {
	steps := make([]string, 0, 6)
	gogCommand := "gog"
	if client := strings.TrimSpace(clientOverride); client != "" {
		gogCommand += " --client " + client
	}
	if !gcloudAvailable {
		steps = append(steps, "Install gcloud, or create/select a Google Cloud project manually")
	} else if result.GcloudAccount == "" {
		steps = append(steps, "Run `gcloud auth login`")
	}
	if result.Project == "" {
		steps = append(steps, "Choose a project with `--gcloud-project PROJECT_ID` or `gcloud config set project PROJECT_ID`")
	} else {
		steps = append(steps,
			"Configure OAuth consent: "+googleCloudConsentURL(result.Project),
			"Create a Desktop OAuth client and download its JSON: "+googleCloudOAuthClientsURL(result.Project),
		)
	}
	if !result.CredentialsSaved {
		steps = append(steps, "Store the download with `"+gogCommand+" auth credentials /path/to/client_secret.json`")
	}
	authCommand := gogCommand
	if readonly {
		authCommand += " --readonly"
	}
	if strings.TrimSpace(c.Email) != "" {
		steps = append(steps, fmt.Sprintf("Authorize with `%s auth add %s --services %s`", authCommand, strings.TrimSpace(c.Email), strings.Join(result.Services, ",")))
	} else {
		steps = append(steps, "Authorize with `"+authCommand+" auth add you@example.com --services "+strings.Join(result.Services, ",")+"`")
	}
	steps = append(steps, "Verify with `gog auth doctor --check`")
	return steps
}

func writeAuthSetupResult(ctx context.Context, result authSetupResult) error {
	if outfmt.IsJSON(ctx) {
		return outfmt.WriteJSON(ctx, stdoutWriter(ctx), result)
	}
	u := ui.FromContext(ctx)
	u.Out().Linef("status\t%s", result.Status)
	if result.GcloudAccount != "" {
		u.Out().Linef("gcloud_account\t%s", result.GcloudAccount)
	}
	if result.Project != "" {
		u.Out().Linef("project\t%s", result.Project)
	}
	u.Out().Linef("services\t%s", strings.Join(result.Services, ","))
	u.Out().Linef("apis\t%s", strings.Join(result.APIs, ","))
	for index, step := range result.NextSteps {
		u.Out().Linef("next_%d\t%s", index+1, step)
	}
	return nil
}

func authSetupGcloudBinary() string {
	if runtime.GOOS == "windows" {
		return "gcloud.cmd"
	}
	return "gcloud"
}

func authSetupGcloudAvailable() bool {
	_, err := exec.LookPath(authSetupGcloudBinary())
	return err == nil
}

func authSetupGcloudValue(ctx context.Context, key string) (string, error) {
	output, err := authSetupRunGcloud(ctx, "config", "get-value", key)
	if err != nil {
		return "", err
	}
	value := strings.TrimSpace(output)
	if value == "(unset)" {
		return "", nil
	}
	return value, nil
}

//nolint:gosec // Fixed gcloud binary; arguments are validated or generated.
func authSetupRunGcloud(ctx context.Context, args ...string) (string, error) {
	command := exec.CommandContext(ctx, authSetupGcloudBinary(), args...)
	command.Env = append(os.Environ(), "CLOUDSDK_CORE_DISABLE_PROMPTS=1")
	output, err := command.CombinedOutput()
	if err != nil {
		detail := strings.TrimSpace(string(output))
		if detail == "" {
			return "", err
		}
		return "", fmt.Errorf("%s: %w", detail, err)
	}
	return string(output), nil
}

func validGoogleCloudProjectID(value string) bool {
	if len(value) < 6 || len(value) > 30 || value[0] < 'a' || value[0] > 'z' {
		return false
	}
	for _, char := range value {
		if (char >= 'a' && char <= 'z') || (char >= '0' && char <= '9') || char == '-' {
			continue
		}
		return false
	}
	return !strings.HasSuffix(value, "-")
}

func googleCloudConsentURL(project string) string {
	return "https://console.cloud.google.com/auth/branding?project=" + url.QueryEscape(project)
}

func googleCloudOAuthClientsURL(project string) string {
	return "https://console.cloud.google.com/auth/clients?project=" + url.QueryEscape(project)
}

package googleauth

import (
	"os/exec"
	"runtime"
)

var startCommand = func(name string, args ...string) error {
	return exec.Command(name, args...).Start() //nolint:gosec // command/args come from fixed OS mapping and caller URL
}

func openBrowser(u string) error {
	name, args := openBrowserCommand(u, runtime.GOOS)
	return startCommand(name, args...)
}

func openBrowserCommand(u string, goos string) (name string, args []string) {
	switch goos {
	case "darwin":
		return "open", []string{u}
	case "windows":
		return "rundll32", []string{"url.dll,FileProtocolHandler", u}
	default:
		return "xdg-open", []string{u}
	}
}

package googleapi

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"sort"
	"strings"
	"sync"

	"github.com/99designs/keyring"
	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"

	"github.com/openclaw/gogcli/internal/authclient"
	"github.com/openclaw/gogcli/internal/config"
	"github.com/openclaw/gogcli/internal/googleauth"
	"github.com/openclaw/gogcli/internal/secrets"
)

type persistingTokenSource struct {
	base   oauth2.TokenSource
	store  secrets.Store
	client string
	email  string
	// Metadata repair uses only scopes returned by the OAuth server, not the
	// requested set. serviceLabel is added only when the observed grant covers
	// the canonical scope set for that service.
	serviceLabel          string
	updateEmailReferences googleauth.EmailReferenceUpdater

	mu  sync.Mutex
	tok secrets.Token
}

type forceRefreshTokenSource interface {
	ForceRefresh(context.Context) (*oauth2.Token, error)
}

var (
	errBaseTokenSourceCannotForceRefresh = errors.New("base token source cannot force refresh")
	errBaseTokenSourceReturnedNilToken   = errors.New("base token source returned nil token")
	errBaseTokenSourceCannotReplaceToken = errors.New("base token source cannot replace refresh token")
	errReauthEmptyRefreshToken           = errors.New("reauthorization returned an empty refresh token")
	errReauthAccountMismatch             = errors.New("reauthorization returned a different account")
)

// isInvalidGrantError checks whether an OAuth2 token refresh error is an
// invalid_grant failure, meaning the stored refresh token is no longer
// usable and must be re-obtained via a full browser-based authorization.
func isInvalidGrantError(err error) bool {
	if err == nil {
		return false
	}

	var retrieveErr *oauth2.RetrieveError

	return errors.As(err, &retrieveErr) && strings.EqualFold(strings.TrimSpace(retrieveErr.ErrorCode), "invalid_grant")
}

type resettableOAuthTokenSource struct {
	mu           sync.Mutex
	source       oauth2.TokenSource
	newSource    func(*oauth2.Token) oauth2.TokenSource
	refreshToken string
}

type tokenAliasDeleter interface {
	DeleteTokenAlias(client string, email string) error
}

func newResettableOAuthTokenSource(newSource func(*oauth2.Token) oauth2.TokenSource, initial *oauth2.Token) *resettableOAuthTokenSource {
	return &resettableOAuthTokenSource{
		source:       newSource(initial),
		newSource:    newSource,
		refreshToken: [REDACTED],
	}
}

func (r *resettableOAuthTokenSource) Token() (*oauth2.Token, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	t, err := r.source.Token()
	if err != nil {
		return nil, fmt.Errorf("resettable oauth token source: %w", err)
	}

	r.rememberRefreshTokenLocked(t)

	return t, nil
}

func (r *resettableOAuthTokenSource) ForceRefresh(context.Context) (*oauth2.Token, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	refreshToken := r.refreshToken
	candidate := r.newSource(&oauth2.Token{RefreshToken: [REDACTED]})

	t, err := candidate.Token()
	if err != nil {
		return nil, fmt.Errorf("resettable oauth token source refresh: %w", err)
	}

	r.source = candidate
	r.rememberRefreshTokenLocked(t)

	return t, nil
}

// ResetRefreshToken replaces the stored refresh token and rebuilds the
// underlying oauth2.TokenSource so the next Token() call uses the new
// token. This is called after a successful auto-reauth to ensure the
// retried request doesn't reuse the revoked refresh token.
func (r *resettableOAuthTokenSource) ResetRefreshToken(refreshToken string) {
	r.mu.Lock()
	defer r.mu.Unlock()

	r.refreshToken = [REDACTED]
	r.source = r.newSource(&oauth2.Token{RefreshToken: [REDACTED]})
}

func (r *resettableOAuthTokenSource) rememberRefreshTokenLocked(t *oauth2.Token) {
	if t == nil {
		return
	}

	if refreshToken := strings.TrimSpace(t.RefreshToken); refreshToken != "" {
		r.refreshToken = [REDACTED]
	}
}

func newPersistingTokenSource(base oauth2.TokenSource, store secrets.Store, client string, email string, tok secrets.Token, serviceLabel string, updateEmailReferences googleauth.EmailReferenceUpdater) oauth2.TokenSource {
	return &persistingTokenSource{
		base:                  base,
		store:                 store,
		client:                client,
		email:                 email,
		serviceLabel:          strings.TrimSpace(serviceLabel),
		updateEmailReferences: updateEmailReferences,
		tok:                   tok,
	}
}

func (p *persistingTokenSource) Token() (*oauth2.Token, error) {
	p.mu.Lock()
	defer p.mu.Unlock()

	t, err := p.base.Token()
	if err != nil {
		return nil, fmt.Errorf("base token source: %w", err)
	}

	return p.persistTokenLocked(t)
}

func (p *persistingTokenSource) ForceRefresh(ctx context.Context) error {
	refresher, ok := p.base.(forceRefreshTokenSource)
	if !ok {
		return errBaseTokenSourceCannotForceRefresh
	}

	p.mu.Lock()
	defer p.mu.Unlock()

	t, err := refresher.ForceRefresh(ctx)
	if err != nil {
		return fmt.Errorf("force token refresh: %w", err)
	}

	_, err = p.persistTokenLocked(t)

	return err
}

// Reauthorize serializes account recovery with ordinary token refreshes. A
// second caller rechecks the token after taking the lock, so concurrent API
// requests cannot launch duplicate browser flows for the same revoked token.
func (p *persistingTokenSource) Reauthorize(
	ctx context.Context,
	reauthorize func(context.Context, secrets.Token) (secrets.Token, error),
) error {
	p.mu.Lock()
	defer p.mu.Unlock()

	// Another request may have repaired the shared source while this request
	// was waiting. In that case the token succeeds now and no browser is needed.
	if t, err := p.base.Token(); err == nil {
		_, persistErr := p.persistTokenLocked(t)
		return persistErr
	} else if !isInvalidGrantError(err) {
		return fmt.Errorf("recheck refresh token before reauthorization: %w", err)
	}

	resetter, ok := p.base.(*resettableOAuthTokenSource)
	if !ok {
		return errBaseTokenSourceCannotReplaceToken
	}

	// A different service client may have completed reauthorization while this
	// source waited on the command-wide coordinator. Adopt that stored token
	// before deciding another browser flow is necessary.
	if latest, storeErr := p.store.GetToken(p.client, p.email); storeErr == nil {
		latestRefreshToken := strings.TrimSpace(latest.RefreshToken)
		if latestRefreshToken != "" && latestRefreshToken != strings.TrimSpace(p.tok.RefreshToken) {
			resetter.ResetRefreshToken(latestRefreshToken)
			p.tok = latest

			if t, tokenErr := p.base.Token(); tokenErr == nil {
				_, persistErr := p.persistTokenLocked(t)
				return persistErr
			} else if !isInvalidGrantError(tokenErr) {
				return fmt.Errorf("use concurrently reauthorized token: %w", tokenErr)
			}
		}
	}

	updated, err := reauthorize(ctx, p.tok)
	if err != nil {
		return err
	}

	updated.RefreshToken = [REDACTED]
	if updated.RefreshToken == "" {
		return errReauthEmptyRefreshToken
	}

	persistEmail := strings.TrimSpace(p.email)
	if updatedEmail := strings.TrimSpace(updated.Email); updatedEmail != "" && !strings.EqualFold(updatedEmail, persistEmail) {
		return fmt.Errorf("%w: got %s, expected %s", errReauthAccountMismatch, updatedEmail, persistEmail)
	}
	updated.Client = p.client
	updated.Email = persistEmail

	if err := p.store.SetToken(p.client, persistEmail, updated); err != nil {
		return fmt.Errorf("persist reauthorized token: %w", err)
	}

	resetter.ResetRefreshToken(updated.RefreshToken)
	p.tok = updated

	return nil
}

func (p *persistingTokenSource) persistTokenLocked(t *oauth2.Token) (*oauth2.Token, error) {
	if t == nil {
		return nil, errBaseTokenSourceReturnedNilToken
	}

	refreshToken := strings.TrimSpace(t.RefreshToken)

	updated := p.tok
	changed := false
	emailChangedFromIdentity := false

	if refreshToken != "" && refreshToken != p.tok.RefreshToken {
		updated.RefreshToken = [REDACTED]
		changed = true
	}

	if accessToken := strings.TrimSpace(t.AccessToken); accessToken != "" && accessToken != strings.TrimSpace(p.tok.AccessToken) {
		updated.AccessToken = accessToken
		changed = true
	}

	if !t.Expiry.IsZero() && !t.Expiry.Equal(p.tok.AccessTokenExpiresAt) {
		updated.AccessTokenExpiresAt = t.Expiry
		changed = true
	}

	if grantedScopes := tokenGrantedScopes(t); len(grantedScopes) > 0 {
		if mergedScopes := mergeStringSet(updated.Scopes, grantedScopes); !stringSlicesEqual(updated.Scopes, mergedScopes) {
			updated.Scopes = mergedScopes
			changed = true
		}

		if p.serviceLabel != "" {
			if canonicalScopes, serviceErr := googleauth.Scopes(googleauth.Service(p.serviceLabel)); serviceErr == nil && scopesContainAll(grantedScopes, canonicalScopes) {
				if mergedServices := mergeStringSet(updated.Services, []string{p.serviceLabel}); !stringSlicesEqual(updated.Services, mergedServices) {
					updated.Services = mergedServices
					changed = true
				}
			}
		}
	}

	if rawIDToken, ok := t.Extra("id_token").(string); ok && strings.TrimSpace(rawIDToken) != "" {
		if identity, identityErr := googleauth.IdentityFromIDToken(rawIDToken); identityErr == nil {
			if strings.TrimSpace(identity.Subject) != "" && strings.TrimSpace(identity.Subject) != strings.TrimSpace(updated.Subject) {
				updated.Subject = strings.TrimSpace(identity.Subject)
				changed = true
			}

			if email := strings.TrimSpace(identity.Email); email != "" && !strings.EqualFold(email, updated.Email) {
				updated.Email = email
				changed = true
				emailChangedFromIdentity = true
			}
		}
	}

	if !changed {
		return t, nil
	}

	persistEmail := strings.TrimSpace(p.email)
	if emailChangedFromIdentity || persistEmail == "" {
		persistEmail = strings.TrimSpace(updated.Email)
	}

	if persistEmail == "" {
		persistEmail = p.email
	}

	if err := p.store.SetToken(p.client, persistEmail, updated); err != nil {
		slog.Warn("persist refreshed token metadata failed", "email", persistEmail, "client", p.client, "err", err)
		return t, nil
	}

	if !strings.EqualFold(p.email, persistEmail) {
		if err := googleauth.MigrateStoredEmailReferences(p.store, p.updateEmailReferences, p.client, p.email, persistEmail); err != nil {
			slog.Warn("migrate renamed token email references failed", "old_email", p.email, "new_email", persistEmail, "client", p.client, "err", err)
		}

		aliasDeleter, ok := p.store.(tokenAliasDeleter)
		if !ok {
			slog.Debug("token store cannot delete renamed email alias", "old_email", p.email, "new_email", persistEmail, "client", p.client)
		} else if err := aliasDeleter.DeleteTokenAlias(p.client, p.email); err != nil {
			slog.Warn("delete renamed token alias failed", "old_email", p.email, "new_email", persistEmail, "client", p.client, "err", err)
		}
	}

	p.tok = updated
	p.email = persistEmail
	slog.Debug("persisted refreshed token metadata", "email", persistEmail, "client", p.client)

	return t, nil
}

func clientCredentialsForAccount(ctx context.Context, dependencies AuthDependencies, email string) (string, config.ClientCredentials, error) {
	client, err := dependencies.resolveClient(email, authclient.ClientOverrideFromContext(ctx))
	if err != nil {
		return "", config.ClientCredentials{}, err
	}

	creds, err := dependencies.readCredentials(client)
	if err != nil {
		return "", config.ClientCredentials{}, err
	}

	return client, creds, nil
}

func tokenSourceForAvailableAccountAuthWithStoredScopeCheck(
	ctx context.Context,
	serviceLabel string,
	email string,
	scopes []string,
	requireStoredGrant bool,
) (oauth2.TokenSource, error) {
	if accessToken := authclient.AccessTokenFromContext(ctx); accessToken != "" {
		slog.Debug("using direct access token", "serviceLabel", serviceLabel)
		return oauth2.StaticTokenSource(&oauth2.Token{AccessToken: accessToken}), nil
	}

	dependencies, err := requireAuthDependencies(ctx)
	if err != nil {
		return nil, err
	}

	serviceAccountTS, saPath, ok, err := tokenSourceForServiceAccountScopes(ctx, dependencies, serviceLabel, email, scopes)
	if err != nil {
		return nil, fmt.Errorf("service account token source: %w", err)
	}

	if ok {
		slog.Debug("using service account credentials", "email", email, "path", saPath)
		return serviceAccountTS, nil
	}

	client, creds, err := clientCredentialsForAccount(ctx, dependencies, email)
	if err != nil {
		return nil, err
	}

	tokenSource, err := tokenSourceForAccountScopesWithStoredScopeCheck(
		ctx,
		dependencies,
		serviceLabel,
		email,
		client,
		creds.ClientID,
		creds.ClientSecret,
		scopes,
		requireStoredGrant,
	)
	if err != nil {
		return nil, fmt.Errorf("token source: %w", err)
	}

	return tokenSource, nil
}

func tokenSourceForAccountScopesWithStoredScopeCheck(
	ctx context.Context,
	dependencies AuthDependencies,
	serviceLabel string,
	email string,
	client string,
	clientID string,
	clientSecret string,
	requiredScopes []string,
	requireStoredGrant bool,
) (oauth2.TokenSource, error) {
	var store secrets.Store

	if s, err := dependencies.openTokens(); err != nil {
		return nil, err
	} else {
		store = s
	}

	var tok secrets.Token

	if t, err := store.GetToken(client, email); err != nil {
		if errors.Is(err, keyring.ErrKeyNotFound) || errors.Is(err, secrets.ErrCorruptStoredToken) {
			return nil, &AuthRequiredError{Service: serviceLabel, Email: email, Client: client, Cause: err}
		}

		return nil, fmt.Errorf("get token for %s: %w", email, err)
	} else {
		tok = t
	}

	if requireStoredGrant && len(tok.Scopes) > 0 && !scopesContainAll(tok.Scopes, requiredScopes) {
		services := normalizeScopeList(tok.Services)
		if len(services) == 0 {
			services = []string{serviceLabel}
		}
		requiredScopes = normalizeScopeList(requiredScopes)

		return nil, &InsufficientScopeError{
			Service:        serviceLabel,
			Email:          email,
			RequiredScopes: requiredScopes,
			GrantedScopes:  normalizeScopeList(tok.Scopes),
			ReauthorizeCommand: fmt.Sprintf(
				"gog auth add %s --services %s --extra-scopes %s --force-consent",
				email,
				strings.Join(services, ","),
				strings.Join(requiredScopes, ","),
			),
		}
	}

	cfg := oauth2.Config{
		ClientID:     clientID,
		ClientSecret: [REDACTED],
		Endpoint:     google.Endpoint,
		Scopes:       requiredScopes,
	}

	// Ensure refresh-token exchanges don't hang forever.
	ctx = context.WithValue(ctx, oauth2.HTTPClient, &http.Client{Timeout: tokenExchangeTimeout})

	baseSource := newResettableOAuthTokenSource(func(t *oauth2.Token) oauth2.TokenSource {
		return cfg.TokenSource(ctx, t)
	}, &oauth2.Token{
		RefreshToken: [REDACTED],
		AccessToken:  [REDACTED],
		Expiry:       tok.AccessTokenExpiresAt,
	})

	return newPersistingTokenSource(baseSource, store, client, email, tok, serviceLabel, dependencies.updateEmailReferences), nil
}

func tokenGrantedScopes(t *oauth2.Token) []string {
	if t == nil {
		return nil
	}

	switch raw := t.Extra("scope").(type) {
	case string:
		return normalizeScopeList(strings.Fields(raw))
	case []string:
		return normalizeScopeList(raw)
	case []any:
		scopes := make([]string, 0, len(raw))
		for _, item := range raw {
			if s, ok := item.(string); ok {
				scopes = append(scopes, s)
			}
		}

		return normalizeScopeList(scopes)
	default:
		return nil
	}
}

func normalizeScopeList(scopes []string) []string {
	set := make(map[string]struct{}, len(scopes))
	for _, scope := range scopes {
		scope = strings.TrimSpace(scope)
		if scope == "" {
			continue
		}
		set[scope] = struct{}{}
	}

	out := make([]string, 0, len(set))
	for scope := range set {
		out = append(out, scope)
	}

	sort.Strings(out)

	return out
}

func mergeStringSet(a []string, b []string) []string {
	return normalizeScopeList(append(append([]string(nil), a...), b...))
}

func scopesContainAll(haystack []string, needles []string) bool {
	if len(needles) == 0 {
		return false
	}

	set := make(map[string]struct{}, len(haystack))
	for _, scope := range normalizeScopeList(haystack) {
		set[scope] = struct{}{}
	}

	for _, scope := range normalizeScopeList(needles) {
		if _, ok := set[scope]; !ok {
			return false
		}
	}

	return true
}

func stringSlicesEqual(a []string, b []string) bool {
	if len(a) != len(b) {
		return false
	}

	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}

	return true
}
